function validate([nums1, nums2, x]) {
  if (!Array.isArray(nums1) || nums1.length < 1 || nums1.length > 1000) return 'nums1 needs 1 to 1000 values.';
  if (!Array.isArray(nums2) || nums2.length !== nums1.length) return 'nums2 must have the same length as nums1.';
  if (nums1.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each nums1 value is an integer from 1 to 1000.';
  if (nums2.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each nums2 value is an integer from 0 to 1000.';
  if (!Number.isInteger(x) || x < 0 || x > 1000000) return 'x is an integer from 0 to 10^6.';
  return null;
}

