function minimumTime(nums1, nums2, x) {
  const n = nums1.length;
  const order = Array.from({ length: n }, (_, i) => i);
  order.sort((a, b) => nums2[a] - nums2[b]);
  const dp = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    const start = nums1[order[i]];
    const growth = nums2[order[i]];
    for (let j = i + 1; j >= 1; j--) {
      dp[j] = Math.max(dp[j], dp[j - 1] + start + growth * j);
    }
  }
  let sum1 = 0;
  let sum2 = 0;
  for (let i = 0; i < n; i++) {
    sum1 += nums1[i];
    sum2 += nums2[i];
  }
  for (let t = 0; t <= n; t++) {
    if (sum1 + sum2 * t - dp[t] <= x) {
      return t;
    }
  }
  return -1;
}

