function minimumTime(nums1, nums2, x) {
  // Simulate every sequence of choices (reset index k, or no reset) for t = 0, 1, ..., n + 1 seconds.
  const n = nums1.length;
  const best = (values, left) => {
    if (left === 0) return values.reduce((a, b) => a + b, 0);
    const grown = values.map((v, i) => v + nums2[i]);
    let low = best(grown, left - 1);
    for (let k = 0; k < n; k++) {
      const next = grown.slice();
      next[k] = 0;
      low = Math.min(low, best(next, left - 1));
    }
    return low;
  };
  for (let t = 0; t <= n + 1; t++) if (best(nums1.slice(), t) <= x) return t;
  return -1;
}

