function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 5);
  const top1 = size === 'large' ? 1000 : pick([3, 10, 1000]);
  const top2 = size === 'large' ? pick([0, 1, 2, 1000]) : pick([0, 1, 3, 10, 1000]);
  const nums1 = Array.from({ length: n }, () => 1 + Math.floor(rand() * top1));
  const nums2 = Array.from({ length: n }, () => Math.floor(rand() * (top2 + 1)));
  const sum1 = nums1.reduce((a, b) => a + b, 0);
  const x = rand() < 0.15 ? 0 : Math.min(1000000, Math.floor(rand() * (sum1 + 2)));
  return [nums1, nums2, x];
}
